(()=>{'use strict';const boxes=document.querySelectorAll('[data-community-ratings]');if(!boxes.length)return;async function load(){try{const r=await fetch('/api/feedback',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();for(const box of boxes){for(const target of['helper','launcher']){const row=(d.ratings||[]).find(x=>x.target===target),node=box.querySelector(`[data-rating="${target}"]`);if(!node)continue;const count=Number(row?.count)||0;node.querySelector('strong').textContent=count?'★ '+Number(row.average).toFixed(1)+' / 5':'Not rated yet';node.querySelector('span').textContent=count?`${count.toLocaleString()} community rating${count===1?'':'s'}`:'Be the first to rate'}}}catch{for(const box of boxes)for(const node of box.querySelectorAll('.rating-metric')){node.querySelector('strong').textContent='—';node.querySelector('span').textContent='Ratings unavailable'}}}load();window.addEventListener('community-rating-updated',load)})();
